  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+1)*70,40+Math.cos(t*0.65+2)*50,0.14,1.8,0.8],
    [400+Math.cos(t*0.55+3)*60,200+Math.sin(t*0.75+1)*70,0.11,2.1,0.9],
    [200+Math.sin(t*0.25+4)*90,220+Math.cos(t*0.45+3)*60,0.09,2.4,1.0],
    [300+Math.cos(t*0.65+2)*80,30+Math.sin(t*0.35+5)*80,0.13,1.6,0.88]
  ];
  let aS=0,iS=0,tW=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2),at=1/(1+d*0.004);
    aS+=(Math.sin(d*f-t*sp)+Math.sin(d*f*1.5-t*sp*0.7+1))*w*at;
    iS+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f*0.4-t*sp*0.4+2.5))*w*at;
    tW+=w;
  }
  aS/=tW;iS/=tW;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.008+t*0.3)*Math.sin(sy*0.01-t*0.25)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
