  const sp2=Math.sin(dist*0.03+ang*5-t*0.8)+Math.sin(dist*0.06-ang*2-t*2);
  const spiral=(sp1*0.3+sp2*0.2);
  const reaction=Math.tanh((aS-iS*0.7+bg*0.3+spiral)*2.2);
  const diffusion=Math.sin(sx*0.3)*Math.sin(sy*0.3)*Math.cos(t*0.5)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const fibril=Math.sin(ang*8+dist*0.02-t*0.5)*Math.cos(ang*5-dist*0.015+t*0.3)*0.15;
  const blend=reaction*0.55+cell*0.2+diffusion*0.1+fibril*0.15,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,80],[15,70,110],[20,120,130],[45,160,130],[140,185,100],[210,195,70],[220,155,65],[200,110,60],[170,60,70],[110,30,65],[50,15,55],[15,10,50],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,cf=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:1.0;
  const hs=Math.sin(ang*2+dist*0.01-t*0.2)*8;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*cf)*lum*edge+hs))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*cf)*lum*edge+hs*0.5))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*cf)*lum*edge-hs*0.7))|0
  ];
}
